            }
            value.NAddresses = inner.ReadSequence(new Asn1Tag(Asn1TagClass.ContextSpecific, 3, true), nested => nested.ReadSetOf(Asn1Tag.Set, static inner => inner.ReadOctetString(Asn1Tag.OctetString)));
